    '<span id="ref-19"></span>Glue P et al. 2016, Clin Pharmacol Drug Dev 5(6):460-468. doi:10.1002/cpdd.254. PMID 27870477. <a href="https://doi.org/10.1002/cpdd.254" rel="noopener">doi.org/10.1002/cpdd.254</a>',
    '<span id="ref-20"></span>Knuijver T, ter Heine R, Schellekens AFA, Heydari P, Lucas L, Westra S, Belgers M, van Oosteren T, Verkes RJ, Kramers C. 2024, J Psychopharmacol 38(5):481-488. doi:10.1177/02698811241237873. PMID 38519421. PMC11102648. <a href="https://europepmc.org/article/PMC/PMC11102648" rel="noopener">europepmc.org/article/PMC/PMC11102648</a>',
