    'Marton S, Gonzalez B, Rodriguez-Bottero S, et al. 2019, Front Pharmacol 10:193. <a href="https://www.frontiersin.org/journals/pharmacology/articles/10.3389/fphar.2019.00193/full" rel="noopener">frontiersin.org/journals/pharmacology/articles/10.3389/fphar.2019.00193/full</a>',
    'Kervadec E, Bezo A, Serreau R, et al. 2026, J Clin Psychopharmacol. doi:10.1097/jcp.0000000000002197. PMID 42228481. <a href="https://doi.org/10.1097/jcp.0000000000002197" rel="noopener">doi.org/10.1097/jcp.0000000000002197</a>',
